export const iconNames = () => Object.keys(P);
export const hasIcon = (n) => Object.prototype.hasOwnProperty.call(P, n);
const missing = new Set();
/** ic(nom, taille, { fill }) — SVG en ligne, currentColor. */
export function ic(n, s = 18, o = {}) {
  const body = (o && o.fill ? PF[n] : null) || P[n];
  if (body == null) {
    if (!missing.has(n)) {
      missing.add(n);
      const err = new Error("Icône inconnue : « " + n + " » (registre icons.js)");
      console.error("[Nova2]", err.message);
      try { if (window.NovaErrors) window.NovaErrors.report(err, "icons"); } catch (e) {}
    }
    return `<svg class="ic ic-missing" width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><title>Icône inconnue : ${n}</title><rect x="3.5" y="3.5" width="17" height="17" rx="4" stroke-dasharray="3 3"/></svg>`;
  }
  return `<svg class="ic" width="${s}" height="${s}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">${body}</svg>`;
}
